steps=[]
for label,ch in labels.items():
    a=[v.copy() for v in patterns]
    for v in a:
        for c in range(NCHAN):
            if c not in ch:
                v[:,c]=0
    f=p/(label+'.xm'); write_xm(f,a,lib)
    steps.append(dict(name='module_load', arguments=dict(path=str(f))))
    steps.append(dict(name='module_render',arguments=dict(rate=48000,amp=12,bits=16,path=str(p/(label+'.wav')))))
(p/'stems.json').write_text(json.dumps(steps))
